func ValidatePrivacySQLiteSnapshot(path, rel string) error {
	db, err := sql.Open(sqlitedriver.Name, SQLiteReadOnlyDSN(path))
	if err != nil {
		return fmt.Errorf("%s: open derived SQLite store %s: %w", StateCorruptCode, rel, err)
	}
	defer db.Close()
