// descriptor-rooted directory used for publication, even if its pathname is
// concurrently replaced.
func SyncPinnedDirectory(root *os.Root) error {
	dir, err := root.Open(".")
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}
