func TestRootedFileLockContentionAndRelease(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	root, err := os.OpenRoot(dir)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = root.Close() })
	first, err := TryFileLockIn(root, "index.lock")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = first.Close() })
	started := time.Now()
	if other, err := TryFileLockIn(root, "index.lock"); !errors.Is(err, ErrFileLockTimeout) {
		if other != nil {
			_ = other.Close()
		}
		t.Fatalf("contending try-lock = %v; want ErrFileLockTimeout", err)
	}
	if time.Since(started) > time.Second {
		t.Fatal("optional cache try-lock waited rather than returning contention")
	}
	if err := first.Close(); err != nil {
		t.Fatal(err)
	}
	second, err := TryFileLockIn(root, "index.lock")
	if err != nil {
		t.Fatalf("reacquire after release: %v", err)
	}
	if err := second.Close(); err != nil {
		t.Fatal(err)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name() != "index.lock" {
		t.Fatalf("rooted cache lock wrote diagnostic or other files: %v", entries)
	}
}

func TestRootedFileLockRejectsInvalidLeaves(t *testing.T) {
	t.Parallel()
	for _, name := range []string{"", ".", "..", "../outside.lock", "nested/index.lock", filepath.Join(t.TempDir(), "absolute.lock")} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			root, err := os.OpenRoot(t.TempDir())
			if err != nil {
				t.Fatal(err)
			}
			defer root.Close()
			if lock, err := TryFileLockIn(root, name); err == nil {
				_ = lock.Close()
				t.Fatalf("accepted invalid leaf %q", name)
			}
		})
	}
	if _, err := TryFileLockIn(nil, "index.lock"); err == nil {
		t.Fatal("accepted nil root")
	}
}

func TestRootedFileLockRejectsAliasesAndDirectories(t *testing.T) {
	t.Parallel()
	for _, kind := range []string{"symlink", "hardlink", "directory"} {
		t.Run(kind, func(t *testing.T) {
			t.Parallel()
			dir, outside := t.TempDir(), t.TempDir()
			target := filepath.Join(outside, "sentinel")
			const sentinel = "outside bytes must remain unchanged"
			if err := os.WriteFile(target, []byte(sentinel), 0o600); err != nil {
				t.Fatal(err)
			}
			leaf := filepath.Join(dir, "index.lock")
			switch kind {
			case "symlink":
				if err := os.Symlink(target, leaf); err != nil {
					t.Skipf("symlink unavailable: %v", err)
				}
			case "hardlink":
				if err := os.Link(target, leaf); err != nil {
					t.Skipf("hardlink unavailable: %v", err)
				}
			case "directory":
				if err := os.Mkdir(leaf, 0o700); err != nil {
					t.Fatal(err)
				}
			}
			root, err := os.OpenRoot(dir)
			if err != nil {
				t.Fatal(err)
			}
			defer root.Close()
			lock, err := TryFileLockIn(root, "index.lock")
			if err == nil {
				_ = lock.Close()
				t.Fatalf("accepted %s cache-lock leaf", kind)
			}
			if kind == "hardlink" && !errors.Is(err, base.ErrFileHardlinked) {
				t.Fatalf("hardlink refusal lost classification: %v", err)
			}
			got, err := os.ReadFile(target)
			if err != nil || string(got) != sentinel {
				t.Fatalf("outside bytes changed: %q (%v)", got, err)
			}
		})
	}
}

func TestRootedFileLockStaysPinnedAcrossPathReplacement(t *testing.T) {
	t.Parallel()
	parent, outside := t.TempDir(), t.TempDir()
	dir, moved := filepath.Join(parent, "cache"), filepath.Join(parent, "cache-moved")
	if err := os.Mkdir(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer root.Close()
	if err := os.Rename(dir, moved); err != nil {
		if runtime.GOOS == "windows" {
			t.Skipf("host does not permit renaming an open directory: %v", err)
