	lock, err := TryFileLockIn(root, "index.lock")
	if err != nil {
		t.Fatal(err)
	}
	if err := lock.Close(); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(moved, "index.lock")); err != nil {
		t.Fatalf("pinned directory did not receive lock: %v", err)
	}
