func TestFactIndexMatchesCurrentGlobalFallback(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	local := factIndexTestRecord("shared", "checkpoint retry")
	global := local
	global.Branch, global.Author, global.Origin = "", "global-author", "imported"
	global.Provenance = []factAnchor{{SessionID: "mem0:public-global"}}
	for _, status := range []string{factmerge.StatusActive, factmerge.StatusRetracted, factmerge.StatusSuperseded} {
		local.Status = status
		merged, ids := retrieval.MergeGlobalFacts([]factRecord{local}, []factRecord{global})
		got := factIndexTestEquivalent(t, env, "global-fallback", append([]factRecord{local}, global), merged, "checkpoint", 10, false)
		if len(got) != 1 {
			t.Fatalf("global fallback produced %d results", len(got))
		}
		if status == factmerge.StatusActive && ids[got[0].ID] {
			t.Fatal("live local copy lost source precedence")
		}
		if status != factmerge.StatusActive && (!ids[got[0].ID] || got[0].Author != global.Author) {
			t.Fatal("inactive local copy suppressed current global payload")
		}
	}
}

func TestFactIndexCancellationNeverBecomesSuccessfulFallback(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	source := factIndexTestCorpus()
	for _, warm := range []bool{false, true} {
		if warm {
			factIndexTestEquivalent(t, env, "cancel", source, source, "checkpoint", 10, false)
		}
		ctx, cancel := context.WithCancel(context.Background())
		cancel()
		got, err := rankFactsIndexedAt(ctx, env, "cancel", source, source, "checkpoint", 10, false, factIndexTestClock())
		if !errors.Is(err, context.Canceled) || len(got) != 0 {
			t.Fatalf("warm=%v cancellation became success/fallback: %+v, %v", warm, got, err)
		}
	}
	ctx, cancel := context.WithDeadline(context.Background(), time.Unix(1, 0))
	defer cancel()
	if _, err := rankFactsIndexedAt(ctx, env, "cancel", source, source, "checkpoint", 10, false, factIndexTestClock()); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("deadline identity changed: %v", err)
	}
}

func TestFactIndexOptionalCacheFailuresRetainScanner(t *testing.T) {
	t.Parallel()
	for _, kind := range []string{"root-is-file", "root-is-symlink", "read-only-root"} {
		t.Run(kind, func(t *testing.T) {
			t.Parallel()
			env := factIndexTestEnv(t)
			source := factIndexTestCorpus()
			switch kind {
			case "root-is-file":
				env.PluginCacheDir = filepath.Join(t.TempDir(), "cache-file")
				if err := os.WriteFile(env.PluginCacheDir, []byte("sentinel"), 0o600); err != nil {
					t.Fatal(err)
				}
			case "root-is-symlink":
				outside := t.TempDir()
				env.PluginCacheDir = filepath.Join(t.TempDir(), "cache-link")
				if err := os.Symlink(outside, env.PluginCacheDir); err != nil {
					t.Skipf("symlink unavailable: %v", err)
				}
				t.Cleanup(func() {
					entries, err := os.ReadDir(outside)
					if err != nil || len(entries) != 0 {
						t.Errorf("unsafe cache root wrote outside: %v (%v)", entries, err)
					}
				})
			case "read-only-root":
				if err := os.Chmod(env.PluginCacheDir, 0o500); err != nil {
					t.Fatal(err)
				}
				t.Cleanup(func() { _ = os.Chmod(env.PluginCacheDir, 0o700) })
				probe := filepath.Join(env.PluginCacheDir, "permission-probe")
				if err := os.WriteFile(probe, []byte("x"), 0o600); err == nil {
					_ = os.Remove(probe)
					t.Skip("host does not enforce read-only directory permissions")
				} else if !errors.Is(err, os.ErrPermission) {
					t.Fatalf("unexpected permission precondition: %v", err)
				}
			}
			factIndexTestEquivalent(t, env, kind, source, source, "checkpoint retry", 10, false)
		})
	}
}

func TestFactIndexConcurrentSourceRevisionsRemainEquivalent(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	baseFacts := factIndexTestCorpus()
	versions := [][]factRecord{baseFacts, factIndexTestClone(t, baseFacts), factIndexTestClone(t, baseFacts)}
	versions[1][1].Text = "unique revision-one checkpoint"
	versions[2][1].Text = "unique revision-two checkpoint"
	versions[2][2].Status = factmerge.StatusRetracted
	start := make(chan struct{})
	errorsFound := make(chan error, 24)
	var group sync.WaitGroup
	for worker := range 8 {
		group.Add(1)
		go func() {
			defer group.Done()
			<-start
			for pass := range 3 {
				source := versions[(worker+pass)%len(versions)]
				want := rankFactsAt(source, "checkpoint revision", 10, false, factIndexTestClock())
				got, err := rankFactsIndexedAt(context.Background(), env, "concurrent", source, source, "checkpoint revision", 10, false, factIndexTestClock())
				if err != nil || !reflect.DeepEqual(got, want) {
					errorsFound <- fmt.Errorf("worker=%d pass=%d mismatched current snapshot: %v", worker, pass, err)
				}
			}
		}()
	}
	close(start)
	group.Wait()
	close(errorsFound)
	for err := range errorsFound {
		t.Error(err)
	}
}
