func factIndexTestEquivalent(t *testing.T, env base.EntireEnv, scope string, source, candidates []factRecord, query string, limit int, includeAll bool) []factRecord {
	t.Helper()
	beforeSource, err := json.Marshal(source)
	if err != nil {
		t.Fatal(err)
	}
	beforeCandidates, err := json.Marshal(candidates)
	if err != nil {
		t.Fatal(err)
	}
	want := rankFactsAt(candidates, query, limit, includeAll, factIndexTestClock())
	got, err := rankFactsIndexedAt(context.Background(), env, scope, source, candidates, query, limit, includeAll, factIndexTestClock())
	if err != nil {
		t.Fatalf("indexed query %q: %v", query, err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("indexed query=%q limit=%d all=%v\n got=%+v\nwant=%+v", query, limit, includeAll, got, want)
	}
	afterSource, err := json.Marshal(source)
	if err != nil {
		t.Fatal(err)
	}
	afterCandidates, err := json.Marshal(candidates)
	if err != nil {
		t.Fatal(err)
	}
	if string(beforeSource) != string(afterSource) || string(beforeCandidates) != string(afterCandidates) {
		t.Fatal("index preparation or ranking mutated caller-owned records")
	}
	return got
}

