func factIndexTestClock() time.Time { return time.Date(2026, 11, 16, 12, 0, 0, 0, time.UTC) }

func factIndexTestEnv(t *testing.T) base.EntireEnv {
	t.Helper()
	return base.EntireEnv{
		PluginConfigDir: t.TempDir(),
		PluginDataDir:   t.TempDir(),
		PluginStateDir:  t.TempDir(),
		PluginCacheDir:  t.TempDir(),
	}
}

func factIndexTestClone(t *testing.T, facts []factRecord) []factRecord {
	t.Helper()
	if facts == nil {
		return nil
	}
	encoded, err := json.Marshal(facts)
	if err != nil {
		t.Fatal(err)
	}
	var cloned []factRecord
	if err := json.Unmarshal(encoded, &cloned); err != nil {
		t.Fatal(err)
	}
	return cloned
}

func factIndexTestRecord(id, text string) factRecord {
	return factRecord{
		ID: id, Text: text, Paths: []string{"architecture.index.rules"},
		Status: factStatusActive, Kind: factKindDecision, Branch: "main", Origin: "authored",
		CreatedAt: factIndexTestClock().Add(-48 * time.Hour), UpdatedAt: factIndexTestClock().Add(-24 * time.Hour),
	}
}

func factIndexTestEquivalent(t *testing.T, env base.EntireEnv, scope string, source, candidates []factRecord, query string, limit int, includeAll bool) []factRecord {
	t.Helper()
	beforeSource, err := json.Marshal(source)
	if err != nil {
		t.Fatal(err)
	}
	beforeCandidates, err := json.Marshal(candidates)
	if err != nil {
		t.Fatal(err)
	}
	want := rankFactsAt(candidates, query, limit, includeAll, factIndexTestClock())
	got, err := rankFactsIndexedAt(context.Background(), env, scope, source, candidates, query, limit, includeAll, factIndexTestClock())
	if err != nil {
		t.Fatalf("indexed query %q: %v", query, err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("indexed query=%q limit=%d all=%v\n got=%+v\nwant=%+v", query, limit, includeAll, got, want)
	}
	afterSource, err := json.Marshal(source)
	if err != nil {
		t.Fatal(err)
	}
	afterCandidates, err := json.Marshal(candidates)
	if err != nil {
		t.Fatal(err)
	}
	if string(beforeSource) != string(afterSource) || string(beforeCandidates) != string(afterCandidates) {
		t.Fatal("index preparation or ranking mutated caller-owned records")
	}
	return got
}

func factIndexTestCorpus() []factRecord {
	rng := rand.New(rand.NewSource(20261116))
	words := []string{"checkpoint", "retry", "backoff", "session", "mysql", "cache", "apple", "banana", "café", "Привет", "東京大学", "数据库", "검색정책", "HTTPParser", "MySQL", "facts_query.go"}
	facts := make([]factRecord, 72)
	for i := range facts {
		terms := make([]string, 1+rng.Intn(28))
		for j := range terms {
			terms[j] = words[rng.Intn(len(words))]
		}
		facts[i] = factIndexTestRecord(fmt.Sprintf("mixed-%03d", i), strings.Join(terms, " "))
		facts[i].UpdatedAt = factIndexTestClock().Add(-time.Duration(rng.Intn(50)) * time.Hour)
		facts[i].Paths = []string{[]string{"architecture.index.rules", "workflow.testing.rules", "preferences.coding.style"}[i%3]}
		facts[i].Kind = []string{"decision", "gotcha", "preference"}[i%3]
		facts[i].Branch = []string{"main", "feature/other"}[i%2]
		if i%9 == 0 {
			facts[i].Status = factmerge.StatusRetracted
		} else if i%13 == 0 {
			facts[i].Status = factmerge.StatusSuperseded
		}
		if i%11 == 0 {
			facts[i].Locus = []string{"facts_query.go"}
		}
		if i%17 == 0 && i+1 < len(facts) {
			facts[i].RelatedIDs = []string{fmt.Sprintf("mixed-%03d", i+1)}
		}
	}
	return facts
}

