const factIndexProcessEnv = "ENTIRE_BRAIN_TEST_FACT_INDEX_REQUEST"

func TestFactIndexProcessHelper(t *testing.T) {
	t.Parallel()
	requestPath := os.Getenv(factIndexProcessEnv)
	if requestPath == "" { t.Skip("subprocess helper") }
	data, err := os.ReadFile(requestPath)
	if err != nil { t.Fatal(err) }
	var request factIndexProcessRequest
	if err := json.Unmarshal(data, &request); err != nil { t.Fatal(err) }
	facts, err := factstore.Load(request.Store)
	if err != nil { t.Fatal(err) }
	env := base.EntireEnv{PluginCacheDir: request.CacheRoot}
	index, err := openFactPreparedIndex(context.Background(), env, request.Scope, facts)
	if err != nil { t.Fatal(err) }
