	if err := index.Close(); err != nil { t.Fatal(err) }
	got, err := rankFactsIndexedAt(context.Background(), env, request.Scope, facts, facts, request.Query, 10, false, factIndexTestClock())
	if err != nil { t.Fatal(err) }
	encoded, err := json.Marshal(factIndexProcessResponse{Reused: reused, Facts: got})
	if err != nil { t.Fatal(err) }
	fmt.Printf("FACT_INDEX_PROCESS %s\\n", encoded)
}

func factIndexRunProcess(t *testing.T, request factIndexProcessRequest) factIndexProcessResponse {
	t.Helper()
	self, err := os.Executable()
	if err != nil { t.Fatal(err) }
	private := t.TempDir()
	requestPath := filepath.Join(private, "request.json")
	data, err := json.Marshal(request)
	if err != nil { t.Fatal(err) }
	if err := os.WriteFile(requestPath, data, 0o600); err != nil { t.Fatal(err) }
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	cmd := execx.NonInteractive(ctx, self, "-test.run=^TestFactIndexProcessHelper$")
	for _, entry := range os.Environ() {
		name, _, _ := strings.Cut(entry, "=")
		if name != "HOME" && !strings.HasPrefix(name, "ENTIRE_") && !strings.HasPrefix(name, "XDG_") && !strings.HasPrefix(name, "GIT_") {
			cmd.Env = append(cmd.Env, entry)
		}
	}
	cmd.Env = append(cmd.Env,
		"HOME="+private,
		"XDG_CONFIG_HOME="+filepath.Join(private,"config"),
		"XDG_DATA_HOME="+filepath.Join(private,"data"),
		"XDG_STATE_HOME="+filepath.Join(private,"state"),
		"XDG_CACHE_HOME="+filepath.Join(private,"cache"),
		"ENTIRE_CONFIG_DIR="+filepath.Join(private,"entire-config"),
		"ENTIRE_TOKEN_STORE=file",
		"ENTIRE_TOKEN_STORE_PATH="+filepath.Join(private,"token.json"),
		"ENTIRE_TEST_AUTH_STORE_FILE="+filepath.Join(private,"auth.json"),
		factIndexProcessEnv+"="+requestPath)
	out, err := cmd.CombinedOutput()
	if err != nil { t.Fatalf("fresh index process: %v\\n%s", err, out) }
	for _, line := range strings.Split(string(out),"\\n") {
		if payload, ok := strings.CutPrefix(line,"FACT_INDEX_PROCESS "); ok {
			var response factIndexProcessResponse
			if err := json.Unmarshal([]byte(payload), &response); err != nil { t.Fatal(err) }
			return response
		}
	}
	t.Fatalf("fresh index process omitted result: %s",out)
	return factIndexProcessResponse{}
}

func TestFactIndexReusesAcrossProcessesAndInvalidatesSameStatChanges(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	store := t.TempDir()
	facts := []factRecord{factIndexTestRecord("one","alpha retry"),factIndexTestRecord("two","banana session")}
	if err := factstore.Write(store,facts); err != nil {t.Fatal(err)}
	request := factIndexProcessRequest{Store:store,CacheRoot:env.PluginCacheDir,Scope:"fresh-process",Query:"alpha"}
	first := factIndexRunProcess(t,request)
	if first.Reused || len(first.Facts)!=1 || first.Facts[0].Text!="alpha retry" {t.Fatalf("first process did not build/use current snapshot: %+v",first)}
	second := factIndexRunProcess(t,request)
	if !second.Reused || !reflect.DeepEqual(second.Facts,first.Facts) {t.Fatalf("second independent process did not reuse prepared snapshot: %+v",second)}
	canonical := filepath.Join(store,factstore.RepositoryPath)
	before,err := os.ReadFile(canonical);if err!=nil {t.Fatal(err)}
	info,err := os.Stat(canonical);if err!=nil {t.Fatal(err)}
	changed := bytes.Replace(before,[]byte(`"alpha retry"`),[]byte(`"omega retry"`),1)
	if bytes.Equal(changed,before)||len(changed)!=len(before) {t.Fatal("invalid same-size source mutation")}
	if err:=os.WriteFile(canonical,changed,0o600);err!=nil {t.Fatal(err)}
	if err:=os.Chtimes(canonical,info.ModTime(),info.ModTime());err!=nil {t.Fatal(err)}
	after,err:=os.Stat(canonical);if err!=nil {t.Fatal(err)}
	if info.Size()!=after.Size() || !info.ModTime().Equal(after.ModTime()) {t.Fatal("same-stat mutation did not preserve signature")}
	request.Query="omega"
	third:=factIndexRunProcess(t,request)
	if third.Reused || len(third.Facts)!=1 || third.Facts[0].Text!="omega retry" {t.Fatalf("fresh process reused an old source revision: %+v",third)}
	fourth:=factIndexRunProcess(t,request)
	if !fourth.Reused || !reflect.DeepEqual(fourth.Facts,third.Facts) {t.Fatalf("changed revision not reusable in next process: %+v",fourth)}
}

func TestFactIndexRevisionIncludesNonLexicalRecordFields(t *testing.T) {
	t.Parallel()
	env:=factIndexTestEnv(t)
	source:=[]factRecord{factIndexTestRecord("one","checkpoint retry")}
	first,err:=openFactPreparedIndex(context.Background(),env,"full-record-revision",source)
	if err!=nil {t.Fatal(err)}
	if first.reused {t.Fatal("new cache unexpectedly reused a generation")}
	if err:=first.Close();err!=nil {t.Fatal(err)}
	second,err:=openFactPreparedIndex(context.Background(),env,"full-record-revision",source)
	if err!=nil {t.Fatal(err)}
	if !second.reused {t.Fatal("unchanged full snapshot was rebuilt")}
	if err:=second.Close();err!=nil {t.Fatal(err)}
	source[0].Author="new-display-author"
	source[0].Provenance=[]factAnchor{{SessionID:"changed-provenance",TurnID:"turn-2"}}
	third,err:=openFactPreparedIndex(context.Background(),env,"full-record-revision",source)
	if err!=nil {t.Fatal(err)}
	defer third.Close()
	if third.reused {t.Fatal("full source revision ignored metadata/provenance change")}
}
