func TestFactIndexReusesAcrossProcessesAndInvalidatesSameStatChanges(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	store := t.TempDir()
	facts := []factRecord{factIndexTestRecord("one", "alpha retry"), factIndexTestRecord("two", "banana session")}
	if err := factstore.Write(store, facts); err != nil {
		t.Fatal(err)
	}
	request := factIndexProcessRequest{Store: store, CacheRoot: env.PluginCacheDir, Scope: "fresh-process", Query: "alpha"}
	first := factIndexRunProcess(t, request)
	if first.Reused || len(first.Facts) != 1 || first.Facts[0].Text != "alpha retry" {
		t.Fatalf("first process did not build/use current snapshot: %+v", first)
	}
	second := factIndexRunProcess(t, request)
	if !second.Reused || !reflect.DeepEqual(second.Facts, first.Facts) {
		t.Fatalf("second independent process did not reuse prepared snapshot: %+v", second)
	}
	canonical := filepath.Join(store, factstore.RepositoryPath)
	before, err := os.ReadFile(canonical)
	if err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(canonical)
	if err != nil {
		t.Fatal(err)
	}
	changed := bytes.Replace(before, []byte(`"alpha retry"`), []byte(`"omega retry"`), 1)
	if bytes.Equal(changed, before) || len(changed) != len(before) {
		t.Fatal("invalid same-size source mutation")
	}
	if err := os.WriteFile(canonical, changed, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Chtimes(canonical, info.ModTime(), info.ModTime()); err != nil {
		t.Fatal(err)
	}
	after, err := os.Stat(canonical)
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() != after.Size() || !info.ModTime().Equal(after.ModTime()) {
		t.Fatal("same-stat mutation did not preserve signature")
	}
	request.Query = "omega"
	third := factIndexRunProcess(t, request)
	if third.Reused || len(third.Facts) != 1 || third.Facts[0].Text != "omega retry" {
		t.Fatalf("fresh process reused an old source revision: %+v", third)
	}
	fourth := factIndexRunProcess(t, request)
	if !fourth.Reused || !reflect.DeepEqual(fourth.Facts, third.Facts) {
		t.Fatalf("changed revision not reusable in next process: %+v", fourth)
	}
}

