func TestFactIndexRebuildsMissingPartialAndIncompatibleGenerations(t *testing.T) {
	t.Parallel()
	for _, variant := range []string{"missing-database", "truncated-database", "missing-descriptor", "partial-descriptor", "schema-version", "tokenizer-version", "wrong-source", "wrong-posting"} {
		t.Run(variant, func(t *testing.T) {
			t.Parallel()
			env := factIndexTestEnv(t)
			source := []factRecord{factIndexTestRecord("one", "apple apple retry"), factIndexTestRecord("two", "apple banana session")}
			databasePath, descriptorPath := factIndexWarmGeneration(t, env, variant, source)
			var err error
			switch variant {
			case "missing-database":
				err = os.Remove(databasePath)
			case "truncated-database":
				err = os.Truncate(databasePath, 100)
			case "missing-descriptor":
				err = os.Remove(descriptorPath)
			case "partial-descriptor":
				err = os.WriteFile(descriptorPath, []byte(`{"revision":`), 0o600)
			case "schema-version", "tokenizer-version", "wrong-source":
				data, readErr := os.ReadFile(descriptorPath)
				if readErr != nil {
					t.Fatal(readErr)
				}
				var descriptor factIndexDescriptor
				if err := json.Unmarshal(data, &descriptor); err != nil {
					t.Fatal(err)
				}
				switch variant {
				case "schema-version":
					descriptor.Revision.Schema++
				case "tokenizer-version":
					descriptor.Revision.Tokenizer++
				case "wrong-source":
					descriptor.Source = strings.Repeat("0", 64)
				}
				data, err = json.Marshal(descriptor)
				if err == nil {
					err = os.WriteFile(descriptorPath, data, 0o600)
				}
			case "wrong-posting":
				// This remains valid SQLite with matching source metadata. Only
				// verification of the committed database bytes rejects the lie.
				db, openErr := sql.Open(sqlitedriver.Name, databasePath)
				if openErr != nil {
					t.Fatal(openErr)
				}
				result, updateErr := db.Exec(`UPDATE fact_index_postings SET frequency=frequency+1 WHERE term='apple' AND document=0`)
				if updateErr != nil {
					_ = db.Close()
					t.Fatal(updateErr)
				}
				n, updateErr := result.RowsAffected()
				if updateErr != nil || n != 1 {
					_ = db.Close()
					t.Fatalf("invalid corruption fixture: affected=%d err=%v", n, updateErr)
				}
				var integrity string
				if err := db.QueryRow(`PRAGMA integrity_check`).Scan(&integrity); err != nil || integrity != "ok" {
					_ = db.Close()
					t.Fatalf("tampered fixture must remain structurally valid SQLite: %q %v", integrity, err)
				}
				err = db.Close()
			}
			if err != nil {
				t.Fatal(err)
			}
			index, err := openFactPreparedIndex(context.Background(), env, variant, source)
			if err != nil {
				t.Fatalf("rebuild of derived cache: %v", err)
			}
			if index.reused {
				_ = index.Close()
				t.Fatal("unverified or incompatible generation was reused")
			}
			if err := index.Close(); err != nil {
				t.Fatal(err)
			}
			factIndexTestEquivalent(t, env, variant, source, source, "apple banana retry", 10, false)
		})
	}
}

func TestFactIndexBusyBuilderFallsBackWithoutWaiting(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	scope := "busy-builder"
	source := []factRecord{factIndexTestRecord("one", "checkpoint retry")}
	_, descriptor := factIndexWarmGeneration(t, env, scope, source)
	if err := os.Remove(descriptor); err != nil {
		t.Fatal(err)
	}
	dir, err := factIndexDirectory(env, scope)
	if err != nil {
		t.Fatal(err)
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer root.Close()
	lock, err := brainstore.TryFileLockIn(root, factIndexLockName)
	if err != nil {
		t.Fatal(err)
	}
	defer lock.Close()
	started := time.Now()
	factIndexTestEquivalent(t, env, scope, source, source, "checkpoint retry", 10, false)
	if time.Since(started) > time.Second {
		t.Fatal("derived-cache contention delayed the authoritative scanner")
	}
	if _, err := os.Stat(descriptor); !os.IsNotExist(err) {
		t.Fatalf("contending reader published without the builder lock: %v", err)
	}
}

func TestFactIndexRejectsHardlinkedDatabaseWithoutChangingTarget(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	scope := "hardlinked-database"
	source := []factRecord{factIndexTestRecord("one", "checkpoint retry")}
	databasePath, _ := factIndexWarmGeneration(t, env, scope, source)
	original, err := os.ReadFile(databasePath)
	if err != nil {
		t.Fatal(err)
	}
	external := filepath.Join(t.TempDir(), "outside.sqlite")
	if err := os.WriteFile(external, original, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(databasePath); err != nil {
		t.Fatal(err)
	}
	if err := os.Link(external, databasePath); err != nil {
		t.Skipf("hardlink fixture unavailable: %v", err)
	}
	factIndexTestEquivalent(t, env, scope, source, source, "checkpoint retry", 10, false)
	after, err := os.ReadFile(external)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(after, original) {
		t.Fatal("optional cache rewrote an external hardlink target")
	}
}

func TestFactIndexBoundsGenerationsAndClosesPrivateSnapshots(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	scope := "bounded-generations"
	for revision := range 6 {
		source := []factRecord{factIndexTestRecord("one", fmt.Sprintf("checkpoint retry revision %d", revision))}
		index, err := openFactPreparedIndex(context.Background(), env, scope, source)
		if err != nil {
			t.Fatal(err)
		}
		private := index.privateDir
		if _, err := os.Stat(private); err != nil {
			_ = index.Close()
			t.Fatalf("reader has no private verified snapshot: %v", err)
		}
		if err := index.Close(); err != nil {
			t.Fatal(err)
		}
		if err := index.Close(); err != nil {
			t.Fatalf("repeated close: %v", err)
		}
		if _, err := os.Stat(private); !os.IsNotExist(err) {
			t.Fatalf("closed reader retained private snapshot: %v", err)
		}
	}
	dir, err := factIndexDirectory(env, scope)
	if err != nil {
		t.Fatal(err)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	databases, descriptors := 0, 0
	for _, entry := range entries {
		switch filepath.Ext(entry.Name()) {
		case ".sqlite":
			databases++
		case ".json":
			descriptors++
		}
	}
	if databases > 2 || descriptors > 2 {
		t.Fatalf("source revisions grew an unbounded cache: databases=%d descriptors=%d", databases, descriptors)
	}
}
