func TestFactIndexRebuildsMissingPartialAndIncompatibleGenerations(t *testing.T) {
	t.Parallel()
	for _, variant := range []string{"missing-database", "truncated-database", "missing-descriptor", "partial-descriptor", "schema-version", "tokenizer-version", "wrong-source", "wrong-posting"} {
		t.Run(variant, func(t *testing.T) {
			t.Parallel()
			env := factIndexTestEnv(t)
			source := []factRecord{factIndexTestRecord("one", "apple apple retry"), factIndexTestRecord("two", "apple banana session")}
			databasePath, descriptorPath := factIndexWarmGeneration(t, env, variant, source)
			var err error
			switch variant {
			case "missing-database":
				err = os.Remove(databasePath)
			case "truncated-database":
				err = os.Truncate(databasePath, 100)
			case "missing-descriptor":
				err = os.Remove(descriptorPath)
			case "partial-descriptor":
				err = os.WriteFile(descriptorPath, []byte(`{"revision":`), 0o600)
			case "schema-version", "tokenizer-version", "wrong-source":
				data, readErr := os.ReadFile(descriptorPath)
				if readErr != nil {
					t.Fatal(readErr)
				}
				var descriptor factIndexDescriptor
				if err := json.Unmarshal(data, &descriptor); err != nil {
					t.Fatal(err)
				}
				switch variant {
				case "schema-version":
					descriptor.Revision.Schema++
				case "tokenizer-version":
					descriptor.Revision.Tokenizer++
				case "wrong-source":
					descriptor.Source = strings.Repeat("0", 64)
				}
				data, err = json.Marshal(descriptor)
				if err == nil {
					err = os.WriteFile(descriptorPath, data, 0o600)
				}
			case "wrong-posting":
				// This remains valid SQLite with matching source metadata. Only
				// verification of the committed database bytes rejects the lie.
				db, openErr := sql.Open(sqlitedriver.Name, databasePath)
				if openErr != nil {
					t.Fatal(openErr)
				}
				result, updateErr := db.Exec(`UPDATE fact_index_postings SET frequency=frequency+1 WHERE term='apple' AND document=0`)
				if updateErr != nil {
					_ = db.Close()
					t.Fatal(updateErr)
				}
				n, updateErr := result.RowsAffected()
				if updateErr != nil || n != 1 {
					_ = db.Close()
					t.Fatalf("invalid corruption fixture: affected=%d err=%v", n, updateErr)
				}
				var integrity string
				if err := db.QueryRow(`PRAGMA integrity_check`).Scan(&integrity); err != nil || integrity != "ok" {
					_ = db.Close()
					t.Fatalf("tampered fixture must remain structurally valid SQLite: %q %v", integrity, err)
				}
				err = db.Close()
			}
			if err != nil {
				t.Fatal(err)
			}
			index, err := openFactPreparedIndex(context.Background(), env, variant, source)
			if err != nil {
				t.Fatalf("rebuild of derived cache: %v", err)
			}
			if index.reused {
				_ = index.Close()
				t.Fatal("unverified or incompatible generation was reused")
			}
			if err := index.Close(); err != nil {
				t.Fatal(err)
			}
			factIndexTestEquivalent(t, env, variant, source, source, "apple banana retry", 10, false)
		})
	}
}

