				if surface == "brief" {
					var out bytes.Buffer
					cmd := &cobra.Command{}
					cmd.SetOut(&out)
					cmd.SetErr(&bytes.Buffer{})
					err := runBrainBrief(context.Background(), cmd, opts, brainBriefOptions{limit: 10, json: true}, "orion")
