					t.Fatalf("%s retrieval: %v\n%s", surface, err, out)
				}
			}
			directory, err := factIndexDirectory(opts.Env, brainDir)
			if err != nil {
				t.Fatal(err)
			}
			markers, err := filepath.Glob(filepath.Join(directory, "*.json"))
			if err != nil || len(markers) != 1 {
				t.Fatalf("runtime did not reuse a committed index: %v, %v", markers, err)
			}
			local, err := factstore.Load(brainDir)
			if err != nil {
				t.Fatal(err)
			}
			local[0].Text = "orion canonical replacement"
			if err = factstore.Write(brainDir, local); err != nil {
				t.Fatal(err)
			}
			out, err := run()
			if err != nil || !strings.Contains(out, "orion canonical replacement") || strings.Contains(out, "orion local retrieval fact") {
