text(await tools.exec_command({cmd:"cat >> internal/cli/facts_index_test.go <<'EOF'

// Each query holds its own fresh logical source snapshot. A writer may finish
// after that load; preparing the older snapshot cannot replace the revision
// chosen by the next query or supply payloads from another revision.
func TestFactIndexConcurrentCanonicalWritesAndFreshReaders(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	store := t.TempDir()
	initial := []factRecord{factIndexTestRecord("one", "checkpoint retry revision zero")}
	if err := factstore.Write(store, initial); err != nil {
		t.Fatal(err)
	}
	loaded, err := factstore.Load(store)
	if err != nil {
		t.Fatal(err)
	}
	changed := []factRecord{factIndexTestRecord("one", "checkpoint retry revision one")}
	writerDone := make(chan error, 1)
	go func() { writerDone <- factstore.Write(store, changed) }()
	if err := <-writerDone; err != nil {
		t.Fatal(err)
	}
	// Deliberately complete an old-generation build after the canonical write.
	factIndexTestEquivalent(t, env, store, loaded, loaded, "checkpoint", 10, false)
	current, err := factstore.Load(store)
	if err != nil {
		t.Fatal(err)
	}
	if current[0].Text == loaded[0].Text {
		t.Fatal("writer did not replace the canonical fixture")
	}
	factIndexTestEquivalent(t, env, store, current, current, "checkpoint", 10, false)

	start := make(chan struct{})
	errorsCh := make(chan error, 4)
	var workers sync.WaitGroup
	workers.Add(1)
	go func() {
		defer workers.Done()
		<-start
		for revision := range 12 {
			facts := []factRecord{factIndexTestRecord("one", fmt.Sprintf("checkpoint retry current revision %d", revision))}
			if err := factstore.Write(store, facts); err != nil {
				errorsCh <- err
				return
			}
		}
	}()
	for range 3 {
		workers.Add(1)
		go func() {
			defer workers.Done()
			<-start
			for range 12 {
				facts, err := factstore.Load(store)
				if err != nil {
					errorsCh <- err
					return
				}
				want := rankFactsAt(facts, "checkpoint retry", 10, false, factIndexTestClock())
				got, err := rankFactsIndexedAt(context.Background(), env, store, facts, facts, "checkpoint retry", 10, false, factIndexTestClock())
				if err != nil || !reflect.DeepEqual(got, want) {
					errorsCh <- fmt.Errorf("reader mixed a canonical revision: got=%v want=%v err=%v", got, want, err)
					return
				}
			}
		}()
	}
	close(start)
	workers.Wait()
	close(errorsCh)
	for err := range errorsCh {
		t.Error(err)
	}
}

// This context requests cancellation after a bounded number of cooperative
// checks, so the test does not depend on a timer racing the SQLite driver.
// It uses a real cancellation channel for database/sql as well as Err callers.
type factIndexCountingCancellation struct {
	context.Context
	cancel context.CancelFunc
	checks atomic.Int64
	after  int64
}

func (ctx *factIndexCountingCancellation) Err() error {
	if ctx.checks.Add(1) >= ctx.after {
		ctx.cancel()
	}
	return ctx.Context.Err()
}

func TestFactIndexCancellationDuringBuildAndVerifiedSnapshotRead(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	source := make([]factRecord, 96)
	for i := range source {
		terms := make([]string, 140)
		for j := range terms {
			terms[j] = fmt.Sprintf("term%dword%d", i, j)
		}
		source[i] = factIndexTestRecord(fmt.Sprintf("document-%d", i), strings.Join(terms, " "))
	}
	digest, signatures, err := factIndexSourceRevision(context.Background(), "cooperative-cancel", source)
	if err != nil {
		t.Fatal(err)
	}
	buildContext, cancelBuild := context.WithCancel(context.Background())
	defer cancelBuild()
	ctx := &factIndexCountingCancellation{Context: buildContext, cancel: cancelBuild, after: 64}
	path, cleanup, err := buildFactIndexDatabase(ctx, digest, source, signatures)
	if cleanup != nil {
		cleanup()
	}
	if !errors.Is(err, context.Canceled) || path != "" || ctx.checks.Load() < 64 {
		t.Fatalf("mid-build cancellation lost: path=%q checks=%d err=%v", path, ctx.checks.Load(), err)
	}

	databasePath, _ := factIndexWarmGeneration(t, env, "cooperative-cancel", source)
	info, err := os.Stat(databasePath)
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() <= 64<<10 {
		t.Fatal("fixture must require more than one verified-copy buffer")
	}
	pinned, err := openFactIndexPinnedDirectory(env, "cooperative-cancel")
	if err != nil {
		t.Fatal(err)
	}
	defer pinned.Close()
	descriptor, err := readFactIndexDescriptor(context.Background(), pinned, digest)
	if err != nil {
		t.Fatal(err)
	}
	readContext, cancelRead := context.WithCancel(context.Background())
	defer cancelRead()
	ctx = &factIndexCountingCancellation{Context: readContext, cancel: cancelRead, after: 2}
	path, private, err := snapshotFactIndex(ctx, pinned, descriptor)
	if !errors.Is(err, context.Canceled) || path != "" || private != "" {
		t.Fatalf("mid-copy cancellation lost: path=%q private=%q err=%v", path, private, err)
	}
	// A cancelled optional operation cannot damage a previously committed cache.
	index, err := openFactPreparedIndex(context.Background(), env, "cooperative-cancel", source)
	if err != nil {
		t.Fatal(err)
