func TestFactIndexPublicationProcessHelper(t *testing.T) {
	t.Parallel()
	requestPath := os.Getenv(factIndexProcessEnv)
	if requestPath == "" {
		t.Skip("publication helper only runs in an isolated subprocess")
	}
	data, err := os.ReadFile(requestPath)
	if err != nil {
		t.Fatal(err)
	}
	var request factIndexProcessRequest
	if err := json.Unmarshal(data, &request); err != nil {
		t.Fatal(err)
	}
	source, err := factstore.Load(request.Store)
	if err != nil {
		t.Fatal(err)
	}
	env := base.EntireEnv{PluginCacheDir: request.CacheRoot}
	digest, signatures, err := factIndexSourceRevision(context.Background(), request.Scope, source)
	if err != nil {
		t.Fatal(err)
	}
	pinned, err := openFactIndexPinnedDirectory(env, request.Scope)
	if err != nil {
		t.Fatal(err)
	}
	defer pinned.Close()
	lock, err := brainstore.TryFileLockIn(pinned.scope, factIndexLockName)
	if err != nil {
		t.Fatal(err)
	}
	defer lock.Close()
	staging, cleanup, err := buildFactIndexDatabase(context.Background(), digest, source, signatures)
	if err != nil {
		t.Fatal(err)
	}
	defer cleanup()
	err = publishFactIndexDatabaseWithBoundary(context.Background(), pinned, staging, digest, len(source), func(stage string) error {
		if stage == request.Boundary {
			// The parent kills this process while a real publication is paused
			// after its SQLite rename and before the descriptor commit record.
			fmt.Println("FACT_INDEX_PUBLICATION_READY " + filepath.Dir(staging))
			_, _ = io.Copy(io.Discard, os.Stdin)
			return errors.New("publication helper stdin closed")
		}
		return nil
	})
	if err == nil {
		t.Fatal("publication helper failed to pause at the requested boundary")
	}
}

func TestFactIndexProcessDeathCannotCommitPartialGeneration(t *testing.T) {
	t.Parallel()
	for _, boundary := range []string{"database_synced", "descriptor_ready"} {
		t.Run(boundary, func(t *testing.T) {
			t.Parallel()
			env := factIndexTestEnv(t)
			store := t.TempDir()
			scope := "process-interruption"
			old := []factRecord{factIndexTestRecord("one", "checkpoint previous")}
			factIndexWarmGeneration(t, env, scope, old)
			current := []factRecord{factIndexTestRecord("one", "checkpoint current")}
			if err := factstore.Write(store, current); err != nil {
				t.Fatal(err)
			}
			private := t.TempDir()
			requestPath := filepath.Join(private, "request.json")
			data, err := json.Marshal(factIndexProcessRequest{Store: store, CacheRoot: env.PluginCacheDir, Scope: scope, Boundary: boundary})
			if err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(requestPath, data, 0600); err != nil {
				t.Fatal(err)
			}
			self, err := os.Executable()
			if err != nil {
				t.Fatal(err)
			}
			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			cmd := execx.NonInteractive(ctx, self, "-test.run=^TestFactIndexPublicationProcessHelper$")
			cmd.Env = factIndexProcessEnvironment(private, requestPath)
			stdin, err := cmd.StdinPipe()
			if err != nil {
				t.Fatal(err)
			}
			defer stdin.Close()
			stdout, err := cmd.StdoutPipe()
			if err != nil {
				t.Fatal(err)
			}
			if err := cmd.Start(); err != nil {
				t.Fatal(err)
			}
			waited := false
			defer func() {
				if !waited {
					_ = cmd.Process.Kill()
					_ = cmd.Wait()
				}
			}()
			line, err := bufio.NewReader(stdout).ReadString('\n')
			staging, ready := strings.CutPrefix(strings.TrimSpace(line), "FACT_INDEX_PUBLICATION_READY ")
			if err != nil || !ready || !strings.HasPrefix(filepath.Base(staging), "entire-brain-fact-index-build-") {
				t.Fatalf("publication helper omitted checkpoint: %q err=%v", line, err)
			}
			defer os.RemoveAll(staging)
			oldIndex, err := openFactPreparedIndex(context.Background(), env, scope, old)
			if err != nil {
				t.Fatal(err)
			}
			if !oldIndex.reused {
				_ = oldIndex.Close()
				t.Fatal("in-flight publication displaced last committed generation")
			}
			if err := oldIndex.Close(); err != nil {
				t.Fatal(err)
			}
			// A second independent reader cannot build over the process lock,
			// but the high-level path must still return the fresh scan result.
			factIndexTestEquivalent(t, env, scope, current, current, "checkpoint current", 10, false)
			if err := cmd.Process.Kill(); err != nil {
				t.Fatal(err)
			}
			if err := cmd.Wait(); err == nil {
				t.Fatal("killed publisher unexpectedly exited successfully")
			}
			waited = true
			index, err := openFactPreparedIndex(context.Background(), env, scope, current)
			if err != nil {
				t.Fatalf("recovery after process death: %v", err)
			}
			if index.reused {
				_ = index.Close()
				t.Fatal("process death published a partial generation")
			}
			if err := index.Close(); err != nil {
				t.Fatal(err)
			}
			factIndexTestEquivalent(t, env, scope, current, current, "checkpoint current", 10, false)
		})
	}
}
