func factIndexRecordSignature(record factRecord) (string, error) {
	data, err := factIndexRecordBytes(record)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

func factIndexRecordBytes(record factRecord) ([]byte, error) {
	if len(record.Text) > factIndexMaxRecordBytes {
		return nil, errFactIndexBudget
	}
	data, err := json.Marshal(record)
	if err != nil {
		return nil, fmt.Errorf("encode fact index record: %w", err)
	}
	if len(data) > factIndexMaxRecordBytes {
		return nil, errFactIndexBudget
	}
	return data, nil
}

