func TestFactIndexFailedSameSourcePublicationRetainsCommittedGeneration(t *testing.T) {
	t.Parallel()
	env := factIndexTestEnv(t)
	scope := "same-source-publication"
	source := []factRecord{factIndexTestRecord("one", "checkpoint retry")}
	factIndexWarmGeneration(t, env, scope, source)
	digest, signatures, err := factIndexSourceRevision(context.Background(), scope, source)
	if err != nil {
		t.Fatal(err)
	}
	pinned, err := openFactIndexPinnedDirectory(env, scope)
	if err != nil {
		t.Fatal(err)
	}
	defer pinned.Close()
	lock, err := brainstore.TryFileLockIn(pinned.scope, factIndexLockName)
	if err != nil {
		t.Fatal(err)
	}
	defer lock.Close()
	staging, cleanup, err := buildFactIndexDatabase(context.Background(), digest, source, signatures)
	if err != nil {
		t.Fatal(err)
	}
	defer cleanup()
	// Byte-distinct SQLite databases may represent the same logical source.
	// The existing descriptor must retain its original blob until the new
	// descriptor commits, even when both publications share the source digest.
	db, err := sql.Open(sqlitedriver.Name, staging)
	if err != nil {
		t.Fatal(err)
	}
	_, changeErr := db.Exec(`PRAGMA user_version=4242`)
	closeErr := db.Close()
	if changeErr != nil || closeErr != nil {
		t.Fatalf("create harmless byte-distinct database: %v, %v", changeErr, closeErr)
	}
	interrupted := errors.New("same-source publication interrupted")
	err = publishFactIndexDatabaseWithBoundary(context.Background(), pinned, staging, digest, len(source), func(stage string) error {
		if stage == "database_synced" {
			return interrupted
		}
		return nil
	})
	if !errors.Is(err, interrupted) {
		t.Fatalf("did not interrupt at database publication boundary: %v", err)
	}
	// Use the reader directly: auto-rebuilding would hide loss of the last
	// committed generation and would be impossible for a contending reader.
	index, err := readFactPreparedIndex(context.Background(), pinned, digest, signatures)
	if err != nil {
		t.Fatalf("same-source failed publication lost the committed generation: %v", err)
	}
	defer index.Close()
	if !index.reused {
		t.Fatal("same-source failed publication rebuilt rather than reusing its commit")
	}
}
EOF
